const $=s=>document.querySelector(s);
const profile={"about": "Ze-Yu Xing\nPhD candidate\nInstitute of Physics, Chinese Academy of Sciences\nBeijing, China\n\nI am a PhD researcher in physics, currently working primarily on open quantum systems and non-equilibrium quantum dynamics. Earlier in my PhD, I focused on non-Hermitian physics. My broader interests include many-body dynamics, statistical mechanics, quantum information, quantum simulation, artificial intelligence, and other emerging interdisciplinary fields.", "research": "My research focuses on non-equilibrium quantum dynamics, particularly in open quantum systems. I study quantum many-body systems far from equilibrium, including relaxation, transport, dissipation, decoherence, and non-Hermitian phenomena. I am also interested in connections with quantum information, quantum simulation, statistical mechanics, and machine learning.", "projects": "OYA-OQS — Liouvillian Lieb-Schultz-Mattis Constraints in Open Quantum Systems\nInvestigating spectral constraints in translationally invariant open quantum many-body systems with strong U(1) symmetry through analytical arguments, exact diagonalization, and tensor-network simulations.\nhttps://github.com/xing-phys/OYA-OQS\n\nssb-qme — Symmetry-Enforced Strong Quantum Mpemba Effect\nDeveloping a symmetry-based mechanism for strong quantum Mpemba effects in symmetry-broken open systems through Liouvillian analysis and quantum-master-equation simulations.\nhttps://github.com/xing-phys/ssb-qme", "publications": "2026  Geometry-adaptive formulation of non-Bloch bands in arbitrary dimensions and spectral instability\nZe-Yu Xing, Yuncheng Xiong, and Haiping Hu\nCommunications Physics 9, 127 (2026)\nhttps://doi.org/10.1038/s42005-026-02546-2\nZe-Yu Xing and Yuncheng Xiong contributed equally.\n\n2025  Universal spreading dynamics in quasiperiodic non-Hermitian systems\nZe-Yu Xing, Shu Chen, and Haiping Hu\nPhysical Review B 111, L180203 (2025)\nhttps://doi.org/10.1103/PhysRevB.111.L180203\n\n2024  Non-Hermitian skin effect in arbitrary dimensions: non-Bloch band theory and classification\nYuncheng Xiong, Ze-Yu Xing, and Haiping Hu\nPreprint · arXiv:2407.01296 (2024)\nhttps://arxiv.org/abs/2407.01296", "notes": "Notes and projects coming soon.", "contact": "Ze-Yu Xing\nInstitute of Physics, Chinese Academy of Sciences\nBeijing, China\n\nGoogle Scholar: https://scholar.google.com/citations?user=qwSu3ekAAAAJ&hl=en\nORCID: https://orcid.org/0009-0009-5655-0187\nGitHub: https://github.com/xing-phys"};
$('#current-year').textContent=new Date().getFullYear();
let storedTheme;try{storedTheme=localStorage.getItem('portfolio-theme')}catch{}
if(storedTheme==='dark')document.body.classList.add('dark');
function themeLabel(){$('.mode-toggle').textContent=document.body.classList.contains('dark')?'☀':'☾';$('.mode-toggle').setAttribute('aria-label',`Switch to ${document.body.classList.contains('dark')?'light':'dark'} theme`)}themeLabel();
$('.mode-toggle').onclick=()=>{document.body.classList.toggle('dark');themeLabel();try{localStorage.setItem('portfolio-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}drawWave()};
function route(){const terminal=location.hash==='#terminal';$('#gui').hidden=terminal;$('#terminal').hidden=!terminal;document.body.classList.toggle('in-terminal',terminal);document.title=terminal?'Ze-Yu Xing — Terminal':'Ze-Yu Xing — Physics & Curiosity';if(terminal){window.scrollTo(0,0);$('#command').focus({preventScroll:true})}else{requestAnimationFrame(drawWave)}}
window.addEventListener('hashchange',route);route();
const commands=['help',...Object.keys(profile),'cv','themes','theme','clear','gui','whoami'];let history=[],historyIndex=0;
function output(command,value){const entry=document.createElement('div');entry.className='output-entry';const prompt=document.createElement('div');prompt.className='output-prompt';prompt.textContent='visitor@xing-phys:~$ '+command;const body=document.createElement('div');body.className='output-text';body.textContent=value;entry.append(prompt,body);$('#terminal-output').append(entry)}
function execute(raw){const value=raw.trim();if(!value)return;history.push(value);historyIndex=history.length;const [command,...args]=value.toLowerCase().split(/\s+/);if(command==='gui'){location.hash='';return}if(command==='cv'){window.open('cv.pdf','_blank','noopener');output(value,'Opening curriculum vitae: /cv.pdf')}else if(command==='clear'){$('#terminal-output').replaceChildren()}else if(profile[command])output(value,profile[command]);else if(command==='help')output(value,'about         A little about me\nresearch      What I study\nprojects      Ongoing research projects\npublications  Selected work\ncv            Open my curriculum vitae\nnotes         Notes and side projects\ncontact       Get in touch\nthemes        Available terminal colors\ntheme <name>  Choose a theme\nwhoami        Meet the visitor\nclear         Clear the screen\ngui           Return to the visual homepage\n\nUse Tab to complete commands and ↑ / ↓ for history.');else if(command==='themes')output(value,'Available themes: violet (default), espresso, light\n\nTry: theme espresso');else if(command==='theme'){if(['violet','espresso','light'].includes(args[0])){$('#terminal').dataset.theme=args[0];output(value,`Theme changed to ${args[0]}.`)}else output(value,'Usage: theme violet | espresso | light')}else if(command==='whoami')output(value,'A curious visitor. Welcome!');else output(value,`Command not found: ${command}\nType help to see what you can explore.`);$('#command').value='';$('#command').focus({preventScroll:true});$('#terminal-form').scrollIntoView({block:'nearest'})}
$('#terminal-form').onsubmit=e=>{e.preventDefault();execute($('#command').value)};
document.querySelectorAll('[data-command]').forEach(el=>el.onclick=()=>execute(el.dataset.command));
$('#command').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.target.value=history[historyIndex]||''}if(e.key==='Tab'&&e.target.value.trim()){const matches=commands.filter(c=>c.startsWith(e.target.value.trim().toLowerCase()));if(matches.length){e.preventDefault();if(matches.length===1)e.target.value=matches[0];else output(e.target.value,matches.join('  '))}}if(e.ctrlKey&&e.key.toLowerCase()==='l'){e.preventDefault();$('#terminal-output').replaceChildren()}};
const canvas=$('#wave'),ctx=canvas.getContext('2d');let waveTime=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
function drawWave(){if($('#gui').hidden)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;ctx.clearRect(0,0,w,h);const dark=document.body.classList.contains('dark');ctx.save();ctx.translate(w*.5,h*.5);ctx.rotate(-.19);for(let j=0;j<49;j++){const v=j/48;ctx.beginPath();for(let i=0;i<=140;i++){const u=i/140;const x=(u-.5)*w*.96;const envelope=Math.sin(u*Math.PI)**.7;const y=(v-.5)*h*.43+Math.sin(u*8+v*5+waveTime)*h*.12*envelope+Math.cos(u*13-v*4-waveTime*.4)*h*.038*envelope;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.strokeStyle=`hsla(${255+v*34},${dark?65:55}%,${dark?72:54}%,${.22+Math.sin(v*Math.PI)*.4})`;ctx.lineWidth=.9;ctx.stroke()}ctx.restore();ctx.fillStyle=dark?'#c6b5f5':'#8666c8';for(const [x,y] of [[.19,.25],[.81,.3],[.79,.72],[.23,.76]]){ctx.beginPath();ctx.arc(w*x,h*y,2,0,Math.PI*2);ctx.fill()}}
function pauseLabel(){$('#pause-wave').textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';$('#pause-wave').setAttribute('aria-label',paused?'Resume wave animation':'Pause wave animation')}pauseLabel();$('#pause-wave').onclick=()=>{paused=!paused;pauseLabel()};let last=0;function animate(t){if(t-last>40){if(!paused&&!document.hidden&&!$('#gui').hidden){waveTime+=.015;drawWave()}last=t}requestAnimationFrame(animate)}new ResizeObserver(drawWave).observe(canvas);requestAnimationFrame(animate);
